// Read-only direct calls into pinned Rapier CCD source, not world stepping.
use rapier3d::{dynamics::{RigidBodyCcd,RigidBodyVelocity,RigidBodyForces,RigidBodyMassProps,RigidBodyPosition},math::{Vector,Rotation,Pose,AngularInertia}};
use serde::Deserialize;use serde_json::json;use std::io::{self,Read};
#[derive(Deserialize)]#[serde(rename_all="camelCase")]
struct Input{linear:[f32;3],angular:[f32;3],translation:[f32;3],rotation:[f32;4],force:[f32;3],torque:[f32;3],inv_mass:[f32;3],inv_inertia:[f32;9],local_com:[f32;3],max_extent:f32,ccd_thickness:f32,dt:f32,next_translation:[f32;3],next_rotation:[f32;4]}
fn v(a:[f32;3])->Vector{Vector::from_array(a)}fn q(a:[f32;4])->Rotation{Rotation::from_xyzw(a[0],a[1],a[2],a[3])}
fn main(){let mut text=String::new();io::stdin().read_to_string(&mut text).unwrap();let items:Vec<Input>=serde_json::from_str(&text).unwrap();let out:Vec<_>=items.into_iter().map(|s|{let ccd=RigidBodyCcd{ccd_thickness:s.ccd_thickness,ccd_enabled:true,..Default::default()};let vel=RigidBodyVelocity{linvel:v(s.linear),angvel:v(s.angular)};let forces=RigidBodyForces{force:v(s.force),torque:v(s.torque),..Default::default()};let mut mass=RigidBodyMassProps::default();mass.effective_inv_mass=v(s.inv_mass);let m=s.inv_inertia;mass.effective_world_inv_inertia=AngularInertia::new(m[0],m[1],m[2],m[4],m[5],m[8]);let predicted=forces.integrate(s.dt,&vel,&mass);let pre=ccd.is_moving_fast(s.dt,&vel,Some((&forces,&mass)),s.max_extent);let pos=RigidBodyPosition{position:Pose::from_parts(v(s.translation),q(s.rotation)),next_position:Pose::from_parts(v(s.next_translation),q(s.next_rotation))};let errors=pos.pose_errors(v(s.local_com));let ccd_vels=pos.interpolate_velocity(1.0/s.dt,v(s.local_com));let post=ccd.is_moving_fast_with_next_position(s.dt,&ccd_vels,&pos,v(s.local_com),s.max_extent);json!({"pre":{"active":pre,"predictedLinear":predicted.linvel.to_array(),"predictedAngular":predicted.angvel.to_array(),"pointSpeed":ccd.max_point_velocity(&predicted,s.max_extent)},"post":{"active":post,"poseErrorTranslation":errors.linear.to_array(),"ccdLinear":ccd_vels.linvel.to_array(),"ccdAngular":ccd_vels.angvel.to_array(),"pointSpeed":ccd.max_point_velocity(&ccd_vels,s.max_extent)}})}).collect();println!("{}",json!({"sourceRevision":"b716d375efc0201003f0cd9ef7168eee0b62c177","items":out}));}
